API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Authentication_Validator, "Authentication Validator", "Azure API Management Policy / OpenID Connect", "Validates JWT tokens against Azure Active Directory.")
    Component(Dynamic_Route_Orchestrator, "Dynamic Route Orchestrator", "Azure API Management Routing", "Routes frontend traffic to appropriate downstream containers.")
    Component(Rate_Limiter_Circuit_Breaker, "Rate Limiter & Circuit Breaker", "Azure API Management Policy", "Protects the fragile legacy mainframe and downstream services by enforcing rate limits and circuit breaker patterns.")
    Component(Claim_Type_Feature_Flag_Evaluator, "Claim-Type Feature Flag Evaluator", "Azure API Management Policy", "Evaluates claim-type feature flags to determine if requests should go to modern or legacy systems.")
}

Rel(Authentication_Validator, Dynamic_Route_Orchestrator, "Enforces security before routing", "HTTPS")
Rel(Dynamic_Route_Orchestrator, Rate_Limiter_Circuit_Breaker, "Checks limits and system health", "HTTPS")
Rel(Dynamic_Route_Orchestrator, Claim_Type_Feature_Flag_Evaluator, "Evaluates migration status for claims", "HTTPS")

@enduml

Integration & ACL Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(integration_acl_container, "Integration & ACL Container") {
    Component(Mainframe_Adapter, "Mainframe Adapter", "IBM MQ with mTLS", "Adapts and secures communication between the cloud integration layer and the legacy mainframe.")
    Component(Anti_Corruption_Layer_ACL_, "Anti-Corruption Layer (ACL)", ".NET / C#", "Isolates legacy mainframe touchpoints and translates data models for the modern cloud platform.")
}

Rel(Mainframe_Adapter, Anti_Corruption_Layer_ACL_, "Translates and forwards messages")

@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_broker, "Message Broker") {
    Component(Outbound_Topic_Router, "Outbound Topic Router", "IBM MQ / AMQP", "Routes domain events and forwards legacy sync events between core services and integration layers.")
}

System_Ext(Azure_Monitor_Sentinel, "Azure Monitor / Sentinel", "Streams security audit logs [HTTPS]")
System_Ext(Integration_ACL_Container, "Integration & ACL Container", "Forwards legacy sync events [IBM MQ]")

Rel(Outbound_Topic_Router, Azure_Monitor_Sentinel, "Streams security audit logs", "HTTPS")
Rel(Outbound_Topic_Router, Integration_ACL_Container, "Forwards legacy sync events", "IBM MQ")

@enduml
